class Router {
  constructor() {
    this.routes = {};
  }

  add(method, pattern, handler) {
    if (!this.routes[method]) {
      this.routes[method] = {};
    }
    this.routes[method][pattern] = handler;
  }

  handle(method, path) {
    const route = this.routes[method][path];
    if (route) {
      return route({ method, path, params: {} });
    }
    return '404';
  }
}

module.exports = Router;
```

