def read_file_counts(path):
    try:
        with open(path, 'r', encoding='utf-8') as file:
            content = file.read()
            words = content.split()
            return len(words)
    except FileNotFoundError:
        raise FileNotFoundError(f"The file {path} does not exist.")
```

