      if (expr[i] === ' ') {
        i++;
      } else if (expr[i] === '+' || expr[i] === '-' || expr[i] === '*' || expr[i] === '/' || expr[i] === '(' || expr[i] === ')') {
        tokens.push({ type: 'operator', value: expr[i] });
