import string

def word_count(text):
    # Remove punctuation and convert to lower case
    translator = str.maketrans('', '', string.punctuation)
    cleaned_text = text.translate(translator).lower()

    # Split into words and count occurrences
    words = cleaned_text.split()
    word_dict = {}
    for word in words:
        if word in word_dict:
            word_dict[word] += 1
        else:
            word_dict[word] = 1

    return word_dict

# Assertions
assert word_count("Hello, world!") == {"hello": 1, "world": 1}
assert word_count("This is a test. This test is only a test.") == {"this": 2, "is": 2, "a": 2, "test": 2, "only": 1}
assert word_count("123 456 123") == {"123": 2, "456": 1}
assert word_count("") == {}

# Run the script to verify
